// The eviction joint's mirrored cmd/mellifera shell (TestEvictionSuppressionPlayJoint,
// task 5.1). cmd/mellifera is package main and cannot be imported, so its
// thin-shell snippets — the frontier snapshot assembly, the five-pass sweep
// order, the eviction/reset vocabulary, and the play closure — are mirrored
// here per the harness convention: every module boundary those snippets JOIN
// is real production code under test (orchestrator.Frontier/Evictions/Repacks,
// the enrich.Queue two-lane dispatcher, stream.Service.Pack/ValidateBuild, the
// store). The ev- prefix stays collision-free in package itest.
package itest

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"io/fs"
	"os"
	"path/filepath"
	"sync"
	"testing"
	"time"

	"github.com/mellifera/mellifera/internal/access"
	"github.com/mellifera/mellifera/internal/orchestrator"
	"github.com/mellifera/mellifera/internal/store"
	"github.com/mellifera/mellifera/internal/stream"
)

// evSuppression mirrors cmd/mellifera's suppressionSet (eviction D3): the
// mutex-guarded mark set whose snapshot rides FrontierIn.Suppressed and that
// the play closure clears. The CONSULTS it feeds are the real policy.
type evSuppression struct {
	mu    sync.Mutex
	items map[string]bool
}

func newEvSuppression() *evSuppression { return &evSuppression{items: make(map[string]bool)} }

func (s *evSuppression) mark(id string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.items[id] = true
}

func (s *evSuppression) clear(id string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.items, id)
}

func (s *evSuppression) contains(id string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.items[id]
}

func (s *evSuppression) snapshot() map[string]bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := make(map[string]bool, len(s.items))
	for id := range s.items {
		out[id] = true
	}
	return out
}

// evDirSize mirrors cmd/mellifera dirSize (disk truth, no ledger).
func evDirSize(path string) int64 {
	var total int64
	_ = filepath.WalkDir(path, func(_ string, d fs.DirEntry, err error) error {
		if err == nil && !d.IsDir() {
			if info, err := d.Info(); err == nil {
				total += info.Size()
			}
		}
		return nil
	})
	return total
}

// evNonces mirrors cmd/mellifera nonces: the build-directory names under one
// item's artifact directory.
func evNonces(itemDir string) []string {
	entries, err := os.ReadDir(itemDir)
	if err != nil {
		return nil
	}
	out := make([]string, 0, len(entries))
	for _, e := range entries {
		if e.IsDir() {
			out = append(out, e.Name())
		}
	}
	return out
}

// evBuildBytes mirrors cmd/mellifera buildBytes: the per-item artifact size
// the frontier's pin cap judges.
func evBuildBytes(root string) map[string]int64 {
	out := make(map[string]int64)
	idDirs, err := os.ReadDir(root)
	if err != nil {
		return out
	}
	for _, idDir := range idDirs {
		if idDir.IsDir() {
			out[idDir.Name()] = evDirSize(filepath.Join(root, idDir.Name()))
		}
	}
	return out
}

// evDecodeDoc mirrors cmd/mellifera decodeItemDoc.
func evDecodeDoc(raw json.RawMessage) map[string]any {
	doc := map[string]any{}
	_ = json.Unmarshal(raw, &doc)
	return doc
}

// evCooldowns mirrors cmd/mellifera streamCooldowns: the pack_failed ledger
// rows under the streams lane, as item → deadline.
func evCooldowns(ctx context.Context, st *store.Store) map[string]time.Time {
	cool := make(map[string]time.Time)
	rows, err := st.ListFailures(ctx)
	if err != nil {
		return cool
	}
	for _, r := range rows {
		if r.PluginID == pbStreamsLane {
			cool[r.ItemID] = r.NextEligibleAt
		}
	}
	return cool
}

// evWatchSnapshot mirrors cmd/mellifera watchState's read: the watched
// predicate input and the eviction LRU recency stamps off ListProgress.
func evWatchSnapshot(ctx context.Context, st *store.Store) (map[string]bool, map[string]time.Time) {
	watched := make(map[string]bool)
	recency := make(map[string]time.Time)
	rows, err := st.ListProgress(ctx, 10_000, access.System())
	if err != nil {
		return watched, recency
	}
	for _, p := range rows {
		if p.PositionSeconds > 0 {
			watched[p.ItemID] = true
		}
		if ts, err := time.Parse(time.RFC3339Nano, p.UpdatedAt); err == nil {
			recency[p.ItemID] = ts
		}
	}
	return watched, recency
}

// evFrontierIn mirrors cmd/mellifera sweepFrontier's snapshot assembly: the
// watched set, the recency stamps, the per-item build bytes, the locked pin
// cap (budget×3/5), and the suppression snapshot ride the real policy input;
// every gated serial enters through QueryItemsBySeries with pbEpisode.
func evFrontierIn(ctx context.Context, st *store.Store, root string, budgetBytes int64, suppressed map[string]bool) (orchestrator.FrontierIn, error) {
	cool := evCooldowns(ctx, st)
	watched, recency := evWatchSnapshot(ctx, st)
	in := orchestrator.FrontierIn{
		Watched:     watched,
		Now:         time.Now(),
		Recency:     recency,
		BuildBytes:  evBuildBytes(root),
		PinCapBytes: budgetBytes * 3 / 5,
		Suppressed:  suppressed,
	}
	libs, err := st.ListLibraries(ctx, access.System())
	if err != nil {
		return in, err
	}
	for _, l := range libs {
		series, err := st.QuerySeries(ctx, l.ID, "", access.System())
		if err != nil {
			return in, err
		}
		for _, sr := range series {
			items, err := st.QueryItemsBySeries(ctx, sr, pbSeriesBacking(sr.Document), access.System())
			if err != nil {
				return in, err
			}
			eps := make([]orchestrator.Episode, 0, len(items))
			for _, it := range items {
				eps = append(eps, pbEpisode(it, cool))
			}
			in.Serials = append(in.Serials, orchestrator.Serial{
				LibraryID: l.ID, StreamsEnabled: l.StreamsEnabled, Episodes: eps,
			})
		}
	}
	return in, nil
}

// evDemotion mirrors cmd/mellifera sweepDemotion (eviction D2): a demoted
// episode's builds die, a named complete-or-partial build resets to none,
// and the item joins the suppression set. Empty in this fixture's passes —
// but the pass runs so the sweep order stays the real composition's.
func evDemotion(ctx context.Context, st *store.Store, root string, demote []string, sup *evSuppression) {
	for _, itemID := range demote {
		itemDir := filepath.Join(root, itemID)
		for _, nonce := range evNonces(itemDir) {
			if evictDirMove(filepath.Join(itemDir, nonce)) {
				evResetNone(ctx, st, itemID, nonce, true)
			}
		}
		sup.mark(itemID)
	}
}

// evRetention mirrors cmd/mellifera sweepRetention: superseded (never the
// document-named) builds die past the dual grace anchor. Fresh builds in
// this fixture never qualify.
func evRetention(ctx context.Context, st *store.Store, root string, grace time.Duration) {
	idDirs, err := os.ReadDir(root)
	if err != nil {
		return
	}
	now := time.Now()
	for _, idDir := range idDirs {
		if !idDir.IsDir() {
			continue
		}
		var nonce string
		var updated time.Time
		if row, err := st.GetItem(ctx, idDir.Name(), access.System()); err != nil {
			if !errors.Is(err, sql.ErrNoRows) {
				continue
			}
		} else {
			streams, _ := evDecodeDoc(row.Document)["streams"].(map[string]any)
			nonce, _ = streams["nonce"].(string)
			updated = row.UpdatedAt
		}
		for _, name := range evNonces(filepath.Join(root, idDir.Name())) {
			if name == nonce {
				continue
			}
			p := filepath.Join(root, idDir.Name(), name)
			info, err := os.Stat(p)
			if err != nil {
				continue
			}
			if now.Sub(info.ModTime()) >= grace && (updated.IsZero() || now.Sub(updated) >= grace) {
				evictDirMove(p)
			}
		}
	}
}

// evBudget mirrors cmd/mellifera sweepBudget: the artifact walk into the
// disk-truth snapshot (live rows, stale/orphan flags, the document-named
// marker), the real orchestrator.Evictions judgment, and the execution
// vocabulary — evict, mark-if-named (eviction D3), reset the record to none.
func evBudget(ctx context.Context, st *store.Store, root string, budgetBytes int64, fronted map[string]bool, sup *evSuppression) {
	if budgetBytes <= 0 {
		return
	}
	idDirs, err := os.ReadDir(root)
	if err != nil {
		return
	}
	_, recency := evWatchSnapshot(ctx, st)
	dirs := make([]orchestrator.ArtifactDir, 0)
	named := make(map[string]bool)
	owner := make(map[string]string)
	for _, idDir := range idDirs {
		if !idDir.IsDir() {
			continue
		}
		live, allStale, current := true, false, ""
		if row, err := st.GetItem(ctx, idDir.Name(), access.System()); err != nil {
			if !errors.Is(err, sql.ErrNoRows) {
				continue // unreadable store: never evict blind
			}
			live, allStale = false, true
		} else if row.Status == "deleted" {
			live, allStale = false, true
		} else {
			streams, _ := evDecodeDoc(row.Document)["streams"].(map[string]any)
			current, _ = streams["nonce"].(string)
		}
		for _, nonce := range evNonces(filepath.Join(root, idDir.Name())) {
			p := filepath.Join(root, idDir.Name(), nonce)
			if nonce == current {
				named[p] = true
			}
			owner[p] = idDir.Name()
			dirs = append(dirs, orchestrator.ArtifactDir{
				Path: p, ItemID: idDir.Name(), Bytes: evDirSize(p), Live: live,
				Stale: allStale || nonce != current,
			})
		}
	}
	for _, path := range orchestrator.Evictions(dirs, recency, fronted, budgetBytes) {
		if evictDirMove(path) {
			if named[path] {
				sup.mark(owner[path])
			}
			evResetNone(ctx, st, owner[path], filepath.Base(path), false)
		}
	}
}

// evIntegrity mirrors cmd/mellifera sweepIntegrity: complete-state builds
// ride the real ValidateBuild verdict into the real Repacks judge; a
// suppressed item's repack skips ahead of the pack gate, exactly the
// composition's consult order.
func evIntegrity(ctx context.Context, st *store.Store, root string, media *stream.Service, enqueue func(string) error, sup *evSuppression) {
	idDirs, err := os.ReadDir(root)
	if err != nil {
		return
	}
	items := make([]orchestrator.IntegrityItem, 0)
	gates := make(map[string]stream.Gate)
	for _, idDir := range idDirs {
		if !idDir.IsDir() {
			continue
		}
		row, err := st.GetItem(ctx, idDir.Name(), access.System())
		if err != nil || row.Status == "deleted" {
			continue
		}
		doc := evDecodeDoc(row.Document)
		streams, _ := doc["streams"].(map[string]any)
		state, _ := streams["state"].(string)
		nonce, _ := streams["nonce"].(string)
		if state != stream.StateComplete {
			continue
		}
		items = append(items, orchestrator.IntegrityItem{
			ItemID: idDir.Name(), Healthy: media.ValidateBuild(idDir.Name(), nonce) == nil,
		})
		ff, _ := doc["ffprobe"].(map[string]any)
		gates[idDir.Name()] = stream.PackGate(ff, false)
	}
	for _, job := range orchestrator.Repacks(items) {
		if sup.contains(job.ItemID) {
			continue
		}
		if gates[job.ItemID] != stream.GateOpen {
			continue
		}
		if err := enqueue(job.ItemID); err != nil {
			continue
		}
	}
}

// evSweep mirrors newSweep's pass order — frontier (demotion riding the same
// pass), retention, budget, integrity — over the real policy and the real
// enqueue seam. Returned jobs/fronted are the caller's assertions.
func evSweep(ctx context.Context, st *store.Store, media *stream.Service, root string, enqueue func(string) error, budgetBytes int64, sup *evSuppression) ([]orchestrator.Job, map[string]bool) {
	in, err := evFrontierIn(ctx, st, root, budgetBytes, sup.snapshot())
	if err != nil {
		return nil, nil
	}
	jobs, fronted, demote := orchestrator.Frontier(in)
	for _, job := range jobs {
		if err := enqueue(job.ItemID); err != nil {
			break
		}
	}
	evDemotion(ctx, st, root, demote, sup)
	evRetention(ctx, st, root, 10*time.Minute) // cmd/mellifera retentionGrace, locked
	evBudget(ctx, st, root, budgetBytes, fronted, sup)
	evIntegrity(ctx, st, root, media, enqueue, sup)
	return jobs, fronted
}

// evFrontierJobs is the pure policy observation the control leg uses: the
// frontier's job decision over the live snapshot, nothing executed.
func evFrontierJobs(ctx context.Context, st *store.Store, root string, budgetBytes int64, suppressed map[string]bool) ([]orchestrator.Job, error) {
	in, err := evFrontierIn(ctx, st, root, budgetBytes, suppressed)
	if err != nil {
		return nil, err
	}
	jobs, _, _ := orchestrator.Frontier(in)
	return jobs, nil
}

// evictDirMove mirrors cmd/mellifera evictDir: .trash sibling, then delete;
// reports whether the directory is gone (the unpublish cue).
func evictDirMove(path string) bool {
	trash := path + ".trash"
	if err := os.Rename(path, trash); err != nil {
		return false
	}
	return os.RemoveAll(trash) == nil
}

// evResetNone mirrors cmd/mellifera resetStreamsState: a policy eviction
// unpublishes the record it took — the budget contract stays complete-only
// (demotion extends to partial), and only the named nonce resets.
func evResetNone(ctx context.Context, st *store.Store, itemID, nonce string, demoted bool) {
	row, err := st.GetItem(ctx, itemID, access.System())
	if err != nil {
		return
	}
	doc := evDecodeDoc(row.Document)
	streams, _ := doc["streams"].(map[string]any)
	state, _ := streams["state"].(string)
	namedNonce, _ := streams["nonce"].(string)
	takes := state == stream.StateComplete || (demoted && state == stream.StatePartial)
	if !takes || namedNonce != nonce {
		return
	}
	doc["streams"] = map[string]any{"state": stream.StateNone}
	b, err := json.Marshal(doc)
	if err != nil {
		return
	}
	row.Document = b
	_ = st.PutItem(ctx, row)
}

// evPlayClosure mirrors cmd/mellifera newPlayClosure over packOnPlay: the
// re-arm (eviction D3) clears the mark BEFORE the pack decision; the
// decision rides the real orchestrator.OnPlay policy; the dispatch rides the
// seam the composition hands in — main.go hands EnqueuePackUrgent. The
// stale-build leg is unreachable in the fixture (the doc never carries a
// complete state with an old master version at play time).
func evPlayClosure(st *store.Store, enqueue func(string) error, sup *evSuppression) func(context.Context, string, bool, *float64) (bool, error) {
	return func(ctx context.Context, itemID string, _ bool, _ *float64) (bool, error) {
		row, err := st.GetItem(ctx, itemID, access.System())
		if err != nil {
			return false, err
		}
		sup.clear(itemID)
		if !orchestrator.OnPlay(pbEpisode(row, evCooldowns(ctx, st)), time.Now()) {
			return false, nil
		}
		if err := enqueue(itemID); err != nil {
			return false, nil
		}
		return true, nil
	}
}

// evAwaitStreamsState mirrors pbAwaitStreams but reports the LAST observed
// streams namespace on timeout — a stalled repack must say what it became,
// not just that it never arrived.
func evAwaitStreamsState(ctx context.Context, t *testing.T, st *store.Store, itemID, want string, timeout time.Duration) map[string]any {
	t.Helper()
	deadline := time.Now().Add(timeout)
	var last map[string]any
	for time.Now().Before(deadline) {
		if row, err := st.GetItem(ctx, itemID, access.System()); err == nil {
			last, _ = evDecodeDoc(row.Document)["streams"].(map[string]any)
			if last != nil && last["state"] == want {
				return last
			}
		}
		time.Sleep(5 * time.Millisecond)
	}
	t.Fatalf("item %s streams state never reached %q within %v; last observed: %v", itemID, want, timeout, last)
	return nil
}
